-- Migration 20261031181218_statutes: generated by drizzle-kit (tables, keys, indexes, checks), the extension, the exclusion constraint and the grants hand-written, reviewed before commit.
-- Reviewed-by: Claude (agent, #1123)
-- Statute and section layer (#1123, part 1 of #1116; D-053, D-001 amended / ADR 0051): global tables (no workspace_id, no RLS) statute_act, statute_section and statute_section_version holding bare-act or synthetic text only, each act and version with a source note and a synthetic mark. statute_section_version_period_excl (btree_gist) rejects overlapping [valid_from, valid_to) versions of one section; a null valid_to is open-ended. Additive only. The app role may only SELECT; the clerk role has no grant; rows are written by the owner role.
CREATE TABLE "statute_act" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"key" text NOT NULL,
	"title" text NOT NULL,
	"short_name" text,
	"year" integer,
	"in_force_from" date NOT NULL,
	"source_note" text NOT NULL,
	"synthetic" boolean NOT NULL,
	CONSTRAINT "statute_act_key_uq" UNIQUE("key")
);
--> statement-breakpoint
CREATE TABLE "statute_section" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"act_id" uuid NOT NULL,
	"section" text NOT NULL,
	"heading" text NOT NULL,
	"search_tsv" "tsvector" GENERATED ALWAYS AS (to_tsvector('simple', "section" || ' ' || "heading")) STORED
);
--> statement-breakpoint
CREATE TABLE "statute_section_version" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"section_id" uuid NOT NULL,
	"text" text NOT NULL,
	"valid_from" date NOT NULL,
	"valid_to" date,
	"amended_by" text,
	"source_note" text NOT NULL,
	"synthetic" boolean NOT NULL,
	CONSTRAINT "statute_section_version_period_check" CHECK ("statute_section_version"."valid_to" is null or "statute_section_version"."valid_to" > "statute_section_version"."valid_from")
);
--> statement-breakpoint
ALTER TABLE "statute_section" ADD CONSTRAINT "statute_section_act_id_statute_act_id_fk" FOREIGN KEY ("act_id") REFERENCES "public"."statute_act"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "statute_section_version" ADD CONSTRAINT "statute_section_version_section_id_statute_section_id_fk" FOREIGN KEY ("section_id") REFERENCES "public"."statute_section"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
CREATE UNIQUE INDEX "statute_section_act_section_uq" ON "statute_section" USING btree ("act_id","section");--> statement-breakpoint
CREATE INDEX "statute_section_search_tsv_idx" ON "statute_section" USING gin ("search_tsv");--> statement-breakpoint
CREATE INDEX "statute_section_version_section_idx" ON "statute_section_version" USING btree ("section_id");--> statement-breakpoint
CREATE EXTENSION IF NOT EXISTS btree_gist;--> statement-breakpoint
ALTER TABLE "statute_section_version" ADD CONSTRAINT "statute_section_version_period_excl" EXCLUDE USING gist ("section_id" WITH =, daterange("valid_from", "valid_to", '[)') WITH &&);--> statement-breakpoint
REVOKE ALL ON "statute_act", "statute_section", "statute_section_version" FROM PUBLIC, causedeck_app, causedeck_clerk;--> statement-breakpoint
GRANT SELECT ON "statute_act", "statute_section", "statute_section_version" TO causedeck_app;
